<?php
namespace App\Http\Controllers\CRM; use App\Http\Controllers\Controller; use App\Models\{Guest,GuestComplaint,GuestFeedback,LoyaltyAccount,MarketingCampaign,Promotion};
class CrmDashboardController extends Controller {public function __invoke(){ $p=auth()->user()->property_id; return view('crm.dashboard',['guests'=>Guest::where('property_id',$p)->count(),'members'=>LoyaltyAccount::where('property_id',$p)->count(),'openComplaints'=>GuestComplaint::where('property_id',$p)->whereNotIn('status',['resolved','closed'])->count(),'avgRating'=>round((float)GuestFeedback::where('property_id',$p)->avg('rating'),1),'activePromos'=>Promotion::where('property_id',$p)->where('is_active',true)->where('starts_at','<=',now())->where('ends_at','>=',now())->count(),'campaigns'=>MarketingCampaign::where('property_id',$p)->latest()->limit(5)->get()]);}}
